#!/usr/bin/env python3
"""Export editable project sources and embed the ZIP for single-file previews."""

import base64
import hashlib
import io
import json
from pathlib import Path
import stat
import xml.etree.ElementTree as ET
import zipfile

ROOT = Path(__file__).resolve().parent.parent
ANDROID_NS = '{http://schemas.android.com/apk/res/android}'
VERSION = ET.parse(ROOT / 'android/AndroidManifest.xml').getroot().get(ANDROID_NS + 'versionName')
FILENAME = f'minefield-source-v{VERSION}.zip'
ARCHIVE_ROOT = f'minefield-v{VERSION}'
SOURCE_STUB = (
    '// Generated by scripts/package-source.py. Source exports contain this empty stub.\n'
    "export const SOURCE_ARCHIVE_BASE64: string = '';\n"
    f'export const SOURCE_ARCHIVE_FILENAME: string = {json.dumps(FILENAME)};\n'
    'export const SOURCE_ARCHIVE_FILE_COUNT: number = 0;\n'
)
APK_STUB = (
    '// Generated by scripts/build-android.py after compiling and signing your own APK.\n'
    "export const APK_BASE64: string = '';\n"
)

TOP_LEVEL = (
    'README.md', 'BUILDING.md', '.gitignore', 'package.json', 'package-lock.json',
    'index.html', 'tsconfig.json', 'vite.config.ts',
)
SOURCE_EXTENSIONS = {'.ts', '.tsx', '.css', '.java', '.xml', '.mjs', '.py', '.html', '.svg', '.webmanifest'}
SKIP_FOLDERS = {'node_modules', '__pycache__', '.android-build', '.android-tools', 'dist', 'build', '.git'}


def source_files():
    # Use an allowlist: no keystores, SDK binaries, environment files, or generated packages.
    result = {name: (ROOT / name).read_bytes() for name in TOP_LEVEL}
    for directory in ('src', 'android', 'scripts', 'public'):
        for path in sorted((ROOT / directory).rglob('*')):
            relative = path.relative_to(ROOT)
            if path.is_symlink() or not path.is_file() or SKIP_FOLDERS.intersection(relative.parts):
                continue
            if path.suffix not in SOURCE_EXTENSIONS:
                continue
            result[relative.as_posix()] = path.read_bytes()
    # Generated payloads must not recursively embed the APK or this archive.
    result['src/apkData.ts'] = APK_STUB.encode('utf-8')
    result['src/sourceData.ts'] = SOURCE_STUB.encode('utf-8')
    return result


def main():
    files = source_files()
    inventory = {name: hashlib.sha256(data).hexdigest() for name, data in sorted(files.items())}
    files['SOURCE_CONTENTS.json'] = (json.dumps({
        'version': VERSION,
        'files': inventory,
        'excluded': ['signing keys', 'SDK/JDK', 'node_modules', 'compiled APKs', 'generated archive payloads'],
    }, indent=2) + '\n').encode('utf-8')
    output = io.BytesIO()
    with zipfile.ZipFile(output, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for name, data in sorted(files.items()):
            info = zipfile.ZipInfo(f'{ARCHIVE_ROOT}/{name}', date_time=(2026, 1, 1, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.create_system = 3
            mode = 0o755 if name.endswith('.py') else 0o644
            info.external_attr = (stat.S_IFREG | mode) << 16
            archive.writestr(info, data)
    payload = output.getvalue()
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        assert archive.testzip() is None
    (ROOT / 'public').mkdir(exist_ok=True)
    (ROOT / 'public' / FILENAME).write_bytes(payload)
    module = (
        '// Auto-generated by scripts/package-source.py. Do not edit by hand.\n'
        f"export const SOURCE_ARCHIVE_BASE64: string = '{base64.b64encode(payload).decode('ascii')}';\n"
        f'export const SOURCE_ARCHIVE_FILENAME: string = {json.dumps(FILENAME)};\n'
        f'export const SOURCE_ARCHIVE_FILE_COUNT: number = {len(files)};\n'
    )
    (ROOT / 'src/sourceData.ts').write_text(module, encoding='utf-8')
    print(f'Source ZIP: public/{FILENAME} ({len(payload):,} bytes, {len(files)} files)')
    print('ZIP embedded in src/sourceData.ts for downloads directly from the preview.')
    print('SHA-256:', hashlib.sha256(payload).hexdigest())


if __name__ == '__main__':
    main()